  initial,
  backToGame,
  onAnnouncement,
  onFinished,
}: ActiveTournamentProps) {
  const [tournament, setTournament] = useState(initial);
  const [session, setSession] = useState(() =>
    initialSession(initial.matches[0]?.boardCode ?? 'np1-4-1', {
      size: 4,
      bestMoves: {},
    }),
  );
  const [confirmLeave, setConfirmLeave] = useState(false);
  const current = useRef(session);
  const board = useRef<BoardFocus>(null);
  const startButton = useRef<HTMLButtonElement>(null);
  const nextTurnButton = useRef<HTMLButtonElement>(null);
  const nextMatchButton = useRef<HTMLButtonElement>(null);
  const championHeading = useRef<HTMLHeadingElement>(null);

  function commit(next: typeof session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  const match = tournament.matches[tournament.currentMatch];
  const playerSeed = match?.players[tournament.currentTurn] ?? null;
  const player = tournament.players.find((item) => item.seed === playerSeed);
  const winner = tournament.players.find((item) => item.seed === match?.winnerSeed);

  useEffect(() => {
    if (tournament.phase === 'ready') startButton.current?.focus();
    if (tournament.phase === 'playing') board.current?.focusRemembered();
    if (tournament.phase === 'next-turn') nextTurnButton.current?.focus();
    if (tournament.phase === 'next-match') nextMatchButton.current?.focus();
    if (tournament.phase === 'complete') championHeading.current?.focus();
  }, [tournament.currentMatch, tournament.currentTurn, tournament.phase]);

  if (!match) return <p>The tournament could not be opened.</p>;

  function resetTurn(code: string): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
  }

  function startTurn(): void {
    setTournament(startTournamentTurn(tournament));
    if (player) onAnnouncement(`Now playing: ${player.name}`);
  }

  function activate(index: number): void {
    if (tournament.phase !== 'playing') return;
    clock.synchronize();
    const nextGame = activateCard(current.current.game, index);
    if (nextGame === current.current.game) return;
    commit({ ...current.current, game: nextGame });
    if (!isWon(nextGame)) return;
    const nextTournament = recordTournamentResult(tournament, {
      elapsedMs: nextGame.elapsedMs,
      moves: nextGame.moves,
    });
    setTournament(nextTournament);
    const finishedPlayer = player;
    if (nextTournament.phase === 'complete') {
      const record = completedTournament(nextTournament);
      if (record) {
        const champion = nextTournament.players.find((item) => item.seed === record.championSeed);
        onAnnouncement(`Champion: ${champion?.name ?? 'Unknown player'}`);
        onFinished(record);
      }
    } else {
      onAnnouncement(
        `${finishedPlayer?.name ?? 'Player'} finished in ${nextGame.moves} moves and ${formatElapsed(nextGame.elapsedMs)}.`,
      );
    }
  }

  function nextTurn(): void {
    const next = nextTournamentTurn(tournament);
    setTournament(next);
    resetTurn(match.boardCode);
    const nextSeed = match.players[1];
    const name = tournament.players.find((item) => item.seed === nextSeed)?.name;
    if (name) onAnnouncement(`Now playing: ${name}`);
  }

  function nextMatch(): void {
    const next = nextTournamentMatch(tournament);
    setTournament(next);
    const nextMatch = next.matches[next.currentMatch];
    if (nextMatch) resetTurn(nextMatch.boardCode);
    const nextSeed = nextMatch?.players[0];
    const name = tournament.players.find((item) => item.seed === nextSeed)?.name;
    if (name) onAnnouncement(`Now playing: ${name}`);
  }

  const currentPlayerName = player?.name ?? 'Player';
  const winnerName = winner?.name ?? 'Match winner';
  const showBoard = tournament.phase === 'playing' || tournament.phase === 'complete';
  const won = isWon(session.game);
  return (
    <section className="tournament-active" aria-labelledby="tournament-round">
      {tournament.phase === 'complete' ? (
        <h3 id="tournament-round" ref={championHeading} tabIndex={-1}>
          Champion: {tournament.players.find((item) => item.seed === tournament.championSeed)?.name}
        </h3>
      ) : (
        <h3 id="tournament-round">Round: {match.round}</h3>
      )}
      {tournament.phase === 'ready' || tournament.phase === 'playing' ? (
        <p className="tournament-now-playing">Now playing: {currentPlayerName}</p>
      ) : tournament.phase === 'next-turn' ? (
        <p className="tournament-now-playing">
          {currentPlayerName} finished: {session.game.moves} moves ·{' '}
          {formatElapsed(session.game.elapsedMs)}
        </p>
      ) : tournament.phase === 'next-match' ? (
        <p className="tournament-now-playing">Match winner: {winnerName}</p>
      ) : null}
      <p className="tournament-intro">
        Both players use this deal. Fewer moves wins; tied moves go to the faster time, then the
        higher seed.
      </p>
      {tournament.phase === 'ready' && (
        <button ref={startButton} className="control" type="button" onClick={startTurn}>
          Start turn
        </button>
      )}
      {tournament.phase === 'next-turn' && (
        <button ref={nextTurnButton} className="control" type="button" onClick={nextTurn}>
          Next turn
        </button>
      )}
      {tournament.phase === 'next-match' && (
        <button ref={nextMatchButton} className="control" type="button" onClick={nextMatch}>
          Next match
        </button>
      )}
      {tournament.phase === 'complete' && (
        <button className="control" type="button" onClick={backToGame}>
          Back to game
        </button>
      )}
      {tournament.phase !== 'complete' && (
        <button className="control" type="button" onClick={() => setConfirmLeave(true)}>
          Leave tournament
        </button>
      )}
      {showBoard && (
        <>
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <dl className="stats tournament-stats">
            <div>
              <dt>Moves</dt> <dd>{session.game.moves}</dd>
            </div>
            <div>
              <dt>Pairs</dt>{' '}
              <dd>
                {session.game.matched.length / 2}/{session.game.deck.length / 2}
              </dd>
            </div>
            <div>
              <dt>Time</dt> <dd>{formatElapsed(session.game.elapsedMs)}</dd>
            </div>
          </dl>
          {won && (
            <p className="victory">
              Every pair found in {session.game.moves} moves and{' '}
              {formatElapsed(session.game.elapsedMs)}.
            </p>
          )}
          <Board key={session.generation} game={session.game} activate={activate} ref={board} />
        </>
      )}
      <BracketTable matches={tournament.matches} players={tournament.players} />
      <LeaveTournamentDialog
        open={confirmLeave}
        close={() => setConfirmLeave(false)}
        leave={backToGame}
      />
    </section>
  );
}
import { useEffect, useRef, useState } from 'react';
import { BracketTable } from './BracketTable.tsx';
import { ActiveTournament } from './ActiveTournament.tsx';
import { freshTournamentDeals } from './fresh-deals.ts';
import {
  decodeTournamentCollection,
  encodeTournamentCollection,
  readTournamentHistory,
  retainRecentTournaments,
  tournamentIdentity,
  unknownTournamentField,
  writeTournamentHistory,
} from './format.ts';
import { createTournament } from './rules.ts';
import { validateTournamentNames } from './names.ts';
import type { Tournament, TournamentRecord } from './rules.ts';
import { TournamentSetup } from './TournamentSetup.tsx';
import './tournament.css';

interface TournamentScreenProps {
  backToGame(): void;
}

export function TournamentScreen({ backToGame }: TournamentScreenProps) {
  const [initialHistory] = useState(readTournamentHistory);
  const [history, setHistory] = useState<readonly TournamentRecord[]>(initialHistory.tournaments);
  const [storageUnavailable, setStorageUnavailable] = useState(initialHistory.unavailable);
  const [active, setActive] = useState<Tournament | null>(null);
  const [formError, setFormError] = useState('');
  const [json, setJson] = useState('');
  const [announcement, setAnnouncement] = useState('');
  const title = useRef<HTMLHeadingElement>(null);

  useEffect(() => title.current?.focus(), []);

  function start(names: readonly string[], count: 4 | 8): void {
    const validation = validateTournamentNames(names);
    if (validation.error) {
      setFormError(validation.error);
      setAnnouncement(validation.error);
      return;
    }
    try {
      const tournament = createTournament(validation.names, freshTournamentDeals(count));
      setFormError('');
      setActive(tournament);
      const firstMatch = tournament.matches[0];
      const firstSeed = firstMatch?.players[0];
      const firstName = tournament.players.find((player) => player.seed === firstSeed)?.name;
      setAnnouncement(firstName ? `Now playing: ${firstName}` : 'Tournament started.');
    } catch {
      setAnnouncement('Could not create tournament deals. Try again.');
    }
  }

  function saveFinished(record: TournamentRecord): void {
    const next = retainRecentTournaments([record, ...history]);
    setHistory(next);
    setStorageUnavailable(!writeTournamentHistory(next));
  }

  function exportHistory(): void {
    setJson(encodeTournamentCollection(history));
    setAnnouncement('Tournament history exported to the JSON box.');
  }

  function loadHistory(): void {
    const imported = decodeTournamentCollection(json);
    if (!imported) {
      const unknown = unknownTournamentField(json);
      setAnnouncement(unknown ? `Unknown field: ${unknown}.` : 'Invalid tournament JSON.');
      return;
    }
    const next = retainRecentTournaments([...imported, ...history]);
    setHistory(next);
    setStorageUnavailable(!writeTournamentHistory(next));
    setAnnouncement(
      `Loaded ${imported.length} ${imported.length === 1 ? 'tournament' : 'tournaments'}.`,
    );
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-title">
      <h2 id="tournament-title" ref={title} tabIndex={-1}>
        Tournament
      </h2>
      <p role="status" aria-live="polite" aria-atomic="true" id="tournament-status">
        {announcement}
      </p>
      {active ? (
        <ActiveTournament
          initial={active}
          backToGame={backToGame}
          onAnnouncement={setAnnouncement}
          onFinished={saveFinished}
        />
      ) : (
        <TournamentSetup error={formError} onBack={backToGame} start={start} />
      )}
      <section className="tournament-exchange" aria-labelledby="tournament-json-title">
        <h3 id="tournament-json-title">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={7}
          spellCheck={false}
          value={json}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button className="control" type="button" onClick={exportHistory}>
            Export tournament
          </button>
          <button
            className="control"
            type="button"
            aria-describedby="tournament-status"
            onClick={loadHistory}
          >
            Load tournament
          </button>
        </div>
        <p className="tournament-exchange-help">
          The JSON contains finished tournaments in the Past tournaments list.
        </p>
      </section>
      <section className="tournament-history" aria-labelledby="past-tournaments-title">
        <h3 id="past-tournaments-title">Past tournaments</h3>
        {storageUnavailable && <p>Progress won't be saved on this device.</p>}
        {history.length === 0 ? (
          <p>No past tournaments yet.</p>
        ) : (
          <ol>
            {history.map((record) => {
              const champion =
                record.players.find((player) => player.seed === record.championSeed)?.name ??
                'Unknown player';
              return (
                <li key={tournamentIdentity(record)}>
                  <details>
                    <summary>
                      Champion: {champion} · {record.players.length} players
                    </summary>
                    <BracketTable matches={record.matches} players={record.players} />
                  </details>
                </li>
              );
            })}
          </ol>
        )}
      </section>
    </section>
  );
}
import { useState } from 'react';
import type { FormEvent } from 'react';

interface TournamentSetupProps {
  error: string;
  onBack(): void;
  start(names: readonly string[], count: 4 | 8): void;
}

export function TournamentSetup({ error, onBack, start }: TournamentSetupProps) {
  const [count, setCount] = useState<4 | 8>(4);
  const [drafts, setDrafts] = useState<string[]>(Array.from({ length: 8 }, () => ''));

  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    start(drafts.slice(0, count), count);
  }

  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-title">
      <h3 id="tournament-setup-title">Start a tournament</h3>
      <form className="tournament-form" onSubmit={submit}>
        <div className="tournament-player-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={count}
            onChange={(event) => setCount(Number(event.currentTarget.value) as 4 | 8)}
          >
            <option value={4}>4 players</option>
            <option value={8}>8 players</option>
          </select>
        </div>
        <div className="tournament-player-fields">
          {drafts.slice(0, count).map((name, index) => {
            const id = `tournament-player-${index + 1}`;
            return (
              <div className="tournament-player-field" key={index}>
                <label htmlFor={id}>Player {index + 1}</label>
                <input
                  id={id}
                  className="control"
                  type="text"
                  autoComplete="off"
                  value={name}
                  aria-describedby={error ? 'tournament-form-error' : undefined}
                  onChange={(event) => {
                    const next = [...drafts];
                    next[index] = event.currentTarget.value;
                    setDrafts(next);
                  }}
                />
              </div>
            );
          })}
        </div>
        {error && (
          <p className="tournament-form-error" id="tournament-form-error">
            {error}
          </p>
        )}
        <div className="tournament-actions">
          <button className="control" type="submit">
            Start tournament
          </button>
          <button className="control" type="button" onClick={onBack}>
            Back to game
          </button>
        </div>
      </form>
    </section>
  );
}
import { useEffect, useRef, useState } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { useGame } from './session/use-game.ts';
import { TournamentScreen } from './tournament/TournamentScreen.tsx';
import './game.css';

export function Game() {
  const [screen, setScreen] = useState<'game' | 'tournament'>('game');
  const controller = useGame(screen === 'game');
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);
  const title = useRef<HTMLHeadingElement>(null);
  const previousScreen = useRef(screen);

  useEffect(() => {
    if (previousScreen.current === 'tournament' && screen === 'game') title.current?.focus();
    previousScreen.current = screen;
  }, [screen]);

  function openTournament(): void {
    controller.pauseForTournament();
    setScreen('tournament');
  }

  function backToGame(): void {
    controller.resumeFromTournament();
    setScreen('game');
  }

  function resume(): void {
    board.current?.focusRemembered();
    controller.resume();
  }
  if (screen === 'tournament') {
    return (
      <main>
        <header>
          <p className="eyebrow">A little focus. A perfect pair.</p>
          <h1>Neon Pairs</h1>
        </header>
        <TournamentScreen backToGame={backToGame} />
      </main>
    );
  }
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1 ref={title} tabIndex={-1}>
          Neon Pairs
        </h1>
      </header>
      <p className="intro">Reveal two cards. Match their shape and marker to keep the pair.</p>
      <Controls
        size={game.size}
        newGame={controller.newGame}
        restart={controller.restart}
        openTournament={openTournament}
      />
      <GameStatus
        game={game}
        best={session.preferences.bestMoves[String(game.size)]}
        celebration={session.celebration}
      />
      <p id="board-help" className="help">
        Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
        reveals a card.
      </p>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={session.announcement}>{session.feedback}</span>
        </p>
      </div>
      <Board key={session.generation} game={game} activate={controller.activate} ref={board} />
      <Reproduction
        game={game}
        generation={session.generation}
        exportSnapshot={controller.exportSnapshot}
        loadBoard={controller.loadBoard}
        loadSnapshot={controller.loadSnapshot}
        notice={session.loadNotice}
        paused={session.paused}
        resume={resume}
      />
    </main>
  );
}
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
  enabled = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      enabled &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    visible.current = !document.hidden;
    if (!enabled) return;
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [enabled, session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}

