import { parseBoardCode } from '../deck.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { roundPlan } from './rules.ts';

export function freshTournamentDeals(playerCount: 4 | 8): string[] {
  const codes: string[] = [];
  const used = new Set<string>();
  let previousSeed: number | undefined;
  for (const round of roundPlan(playerCount)) {
    for (let match = 0; match < round.count; match += 1) {
      let code = freshBoardCode(round.size, previousSeed);
      while (used.has(code)) code = freshBoardCode(round.size, parseBoardCode(code)?.seed);
      const parsed = parseBoardCode(code);
      if (!parsed) throw new Error('Could not create a tournament deal.');
      codes.push(code);
      used.add(code);
      previousSeed = parsed.seed;
    }
  }
  return codes;
}
import { useEffect, useRef } from 'react';

interface LeaveTournamentDialogProps {
  close(): void;
  leave(): void;
  open: boolean;
}

export function LeaveTournamentDialog({ open, close, leave }: LeaveTournamentDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const keepPlaying = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    const element = dialog.current;
    if (!open || !element || element.open) return;
    element.showModal();
    keepPlaying.current?.focus();
  }, [open]);

  function confirmLeave(): void {
    dialog.current?.close();
    leave();
  }

  return (
    <dialog className="tournament-dialog" ref={dialog} onClose={close}>
      <h3>Leave tournament?</h3>
      <p>The unfinished tournament will be discarded.</p>
      <div className="tournament-actions">
        <button
          ref={keepPlaying}
          className="control"
          type="button"
          onClick={() => dialog.current?.close()}
        >
          Keep playing
        </button>
        <button className="control" type="button" onClick={confirmLeave}>
          Leave
        </button>
      </div>
    </dialog>
  );
}

